import sys
from collections import deque

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print(0)
        return

    m = int(data[0])
    n = int(data[1])

    if m <= 0 or n <= 0:
        print(0)
        return

    grid = []
    index = 2
    for i in range(m):
        if index < len(data):
            grid.append(list(data[index]))
            index += 1
        else:
            grid.append(['0'] * n)

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    islands = 0

    for i in range(m):
        for j in range(n):
            if grid[i][j] == '1':
                islands += 1
                queue = deque([(i, j)])
                grid[i][j] = '0'

                while queue:
                    x, y = queue.popleft()
                    for dx, dy in directions:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == '1':
                            grid[nx][ny] = '0'
                            queue.append((nx, ny))

    print(islands)

if __name__ == "__main__":
    main()
